class RequestEntity{const RequestEntity({required this.id,required this.name,required this.phone,required this.message,required this.status,this.email,this.service,this.provider,this.createdAt});final String id,name,phone,message,status;final String? email;final Map<String,dynamic>? service,provider;final DateTime? createdAt;factory RequestEntity.fromJson(Map<String,dynamic>j)=>RequestEntity(id:'${j['id']}',name:j['name']??'',phone:j['phone']??'',message:j['message']??'',status:j['status']??'NEW',email:j['email'],service:j['service'],provider:j['provider'],createdAt:j['created_at']==null?null:DateTime.tryParse(j['created_at']));}
